use vstd::prelude::*;

verus! {

fn linear_search(a: &Vec<i32>, e: i32) -> (result: usize)
    ensures
        // If we found an index < len, it's the first occurrence of e
        if result < a.len() {
            a[result] == e
            && forall j: usize :: j < result ==> a[j] != e
        }
        // Otherwise, e does not occur in the whole vector
        else {
            result == a.len()
            && forall j: usize :: j < a.len() ==> a[j] != e
        }
{
    // We iterate idx from 0 up to a.len()
    for (idx, &val) in a.iter().enumerate()
        invariant
            // idx never exceeds the length
            idx <= a.len(),
            // we have not seen e in any of the elements before idx
            forall j: usize :: j < idx ==> a[j] != e,
        decreases
            // each loop iteration brings us closer to a.len()
            a.len() - idx,
    {
        if val == e {
            // as soon as we see e, we return the first such idx
            return idx;
        }
    }

    // if we exit the loop, we never found e
    a.len()
}

} // verus!

